# -*- coding: utf-8 -*-
"""UTF-9 encoding/decoding module
"""

from bitarray import bitarray as _bitarray

def utf9encode(string):
    """utf-9 encode a unicode string"""
    bits = _bitarray()
    for char in string:
        for idx, byte in enumerate(char.encode('utf-8')):
            bits.append(idx)
            bits.extend('{0:b}'.format(ord(byte)).zfill(8))
    return bits.tobytes()

def utf9decode(data):
    """utf-9 decode a utf-9 encoded string"""
    bits = _bitarray()
    bits.frombytes(data)
    chunks = (bits[x:x+9] for x in xrange(0, len(bits), 9))
    string = u''
