# -*- coding: utf-8 -*-
"""UTF-9 encoding/decoding for unicode strings.

There are two functions in this module:
    utf9encode - encodes a unicode string to utf-9
    utf9decode - decodes an utf-9 encoded string to unicode
"""

from bitarray import bitarray as _bitarray

def utf9encode(string):
    """Encodes a unicode string to utf-9"""
    bits = _bitarray()
    for char in string:
        for idx, byte in enumerate(char.encode('utf-8')):
            bits.append(idx)
            bits.extend('{0:b}'.format(ord(byte)).zfill(8))
    return bits.tobytes()

def utf9decode(data):
    """Decodes an utf-9 encoded string to unicode"""
    bits = _bitarray()
    bits.frombytes(data)
    chunks = (bits[x:x+9] for x in xrange(0, len(bits), 9))
    string = u''
    codepoint = ''
    for chunk in chunks:
        if len(chunk) < 9:
            break
        if chunk[0] == 0:
            codepoint, string = '', string + codepoint.decode('utf-8')
        codepoint += chr(int(chunk[1:].to01(), 2))
    return string + codepoint.decode('utf-8')

